def metrics(cs):
 common=[c for c in cs if c['rarity']=='C'];nonland=[c for c in common if 'Land' not in c['type']]
 return {'cards':len(cs),'rarity':dict(collections.Counter(c['rarity'] for c in cs)),'lands':sum('Land' in c['type'] for c in cs),'doubleFaced':sum(c['layout']=='transform' for c in cs),'commonCreatures':sum('Creature' in c['type'] for c in nonland),'commonEnchantmentCreatures':sum('Enchantment Creature' in c['type'] for c in nonland),'commonEnchantments':sum('Enchantment' in c['type'] for c in nonland),'commonFoodSources':sum('create a food token' in c['rules'].lower() or 'Artifact — Food' in c['type'] for c in nonland),'commonManifestFate':sum('manifest fate' in c['rules'].lower() for c in nonland),'commonForetell':sum('foretell' in c['rules'].lower() for c in nonland),'commonEscape':sum('escape' in c['rules'].lower() for c in nonland),'commonGift':sum('Gift a Food' in c['rules'] for c in nonland),'commonConstellation':sum('Constellation' in c['rules'] for c in nonland),'commonCreatureByColor':dict(collections.Counter(c['color'] for c in nonland if 'Creature' in c['type']))}
summary={'status':'isolated-playtest-candidate-not-live','baseDatasetVersion':base['datasetVersion'],'changedCards':len(changes),'before':metrics(base['cards']),'after':metrics(cards),'warnings':['No played matches have been performed.','Source briefs are a first pass; unresolved passage verification remains labelled.','Hunter approved WU Penelope and explicitly selected actual sacrifice for Iphigenia. Slot 015 now remains UB; its proposed rate still needs testing.','The Ordeals still grant Survival to their enchanted creatures; source names remain where self-reference would change meaning.','The seven Studio notes remain open until actual implementation is verified.','Candidate references need a production refresh before integration.']}
assert len(cards)==309 and len({c['id'] for c in cards})==309
assert summary['before']['rarity']==summary['after']['rarity'] and summary['after']['lands']==40 and summary['after']['doubleFaced']==1
protected=['id','number','rarity','primaryArt','credit','source','imageUrl','productLayer']
for old,new in zip(base['cards'],cards):
 for k in protected: assert old.get(k)==new.get(k),(old['id'],k)
for name,value in [('candidate-cards.json',{'schema':'odyssey-design-candidate/v1','summary':summary,'cards':cards}),('candidate-changes.json',changes),('candidate-summary.json',summary)]:
 (OUT/name).write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n')
print(json.dumps(summary,indent=2))
